using FluentAssertions;using Microsoft.AspNetCore.Hosting;using Microsoft.AspNetCore.Mvc.Testing;namespace CGSmartK.IntegrationTests;public class RouteTests:IClassFixture<WebApplicationFactory<Program>>{private readonly HttpClient client;public RouteTests(WebApplicationFactory<Program> factory){client=factory.WithWebHostBuilder(b=>b.UseEnvironment("Development")).CreateClient(new(){AllowAutoRedirect=false});}[Fact]public async Task Dashboard_is_available(){var response=await client.GetAsync("/");response.IsSuccessStatusCode.Should().BeTrue();}[Fact]public async Task Employee_cannot_open_admin(){var response=await client.GetAsync("/Knowledge");response.StatusCode.Should().Be(System.Net.HttpStatusCode.Forbidden);}[Fact]public async Task Admin_can_open_upload(){var response=await client.GetAsync("/Knowledge/Upload?as=admin");response.IsSuccessStatusCode.Should().BeTrue();}[Fact]public async Task Post_without_antiforgery_is_rejected(){var response=await client.PostAsync("/Chat/Ask",new FormUrlEncodedContent(new Dictionary<string,string>{{"question","Synthetic question"}}));response.StatusCode.Should().Be(System.Net.HttpStatusCode.BadRequest);}}
